/**
 * @method
 * @name fn_PrelistPageSearch
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_PrelistPageSearch = function() {
    form.action = '/list/prelistPage.do';
    form.method.setValue('prelistPageSearch');
    form.submit();
};
/**
 * @method
 * @name fn_ChangePage
 * @description desc
 * @param {string} pageIndex desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ChangePage = function(pageIndex) {
    //	if( eval(form.nowPage.value) <= eval(form.billLstSaveStatCd.value) || eval(pageIndex) <= (eval(form.billLstSaveStatCd.value) + 1)) {
    if (eval(pageIndex) <= (eval(form.billLstSaveStatCd.getValue()) + 1)) {
        form.nowPage.setValue(pageIndex);

        //		window.status=pageIndex + "page로 이동중" ;
        if (eval(pageIndex) < 5) {
            form.action = '/list/prelist.do';
            form.method.setValue('prelistSearch');
        } else {
            form.action = '/list/prelistEtc.do';
            form.method.setValue('prelistSearchEtc');
        }
        form.submit();
    } else {
        alert("현재페이지의 항목들을 저장후에 다음 페이지로 이동할수 있습니다.");
        return;
    }
};
/**
 * @method
 * @name fn_CheckTrnsmYn
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CheckTrnsmYn = function() {
    var trnsmYn = form["trnsmYn"].getValue();
    if (trnsmYn == 'Y') {
        // 이미 제출되었다면 신규작성/수정/삭제 할 수 없다.
        alert("이미 제출 되어 신규작성/수정/삭제 할 수 없습니다.");
        return false;
    }
    return true;
};
