/**
 * @method
 * @name viewFormNameAndData
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.viewFormNameAndData = function() {
    var i = 0;
    var formData = "";
    for (; i < form.length; i++) {
        formData += "[" + form[i].name + "] =  " + form[i].getValue() + "\t";
        if (i % 4 == 0) formData += "\n\n";
        0;
    }
    alert(formData);
    //	alert(form["bzProcsNo"].value);

};
/**
 * @method
 * @name fn_SetCheckBoxValue
 * @description desc
 * @param {string} checkboxName desc
 * @param {string} formParamName desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_SetCheckBoxValue = function(checkboxName, formParamName) {
    if (form[checkboxName].checked) form[formParamName].setValue("Y");

    else form[formParamName].setValue("N");
};
/**
 * @method
 * @name fn_SetRadioValue
 * @description desc
 * @param {string} radioName desc
 * @param {string} formParamName desc
 * @param {string} msg desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_SetRadioValue = function(radioName, formParamName, msg) {
    var i = 0;
    for (; i < form[radioName].length; i++) {
        if (form[radioName][i].checked == true) {
            form[formParamName].setValue(form[radioName][i].getValue());
            break;
        }
    }
    if (i == form[radioName].length) {
        alert(msg + " 항목을 선택해주세요.");
        form[radioName][0].focus();
        return false;
    }
    //	alert(form[formParamName].value) ;
    return true;
};
/**
 * @method
 * @name fn_SetSelect
 * @description desc
 * @param {string} obj desc
 * @param {string} p_value desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_SetSelect = function(obj, p_value) {
    for (var i = 0; i < obj.length; i++) {
        if (obj[i].getValue() == p_value) obj[i].selected = true;
    }
};
/**
 * @method
 * @name getByteLength
 * @description desc
 * @param {string} szValue desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getByteLength = function(szValue) {
    var tcount = 0;
    var tmpStr = new String(szValue);
    var temp = tmpStr.length;
    var onechar;
    for (k = 0; k < temp; k++) {
        onechar = tmpStr.charAt(k);
        if (escape(onechar).length > 4) tcount += 2;

        else tcount += 1;
    }
    return tcount;
};


/* 최대길이 검사 , vars : 입력변수명의 배열, names : 항목명의 배열, maxes : 최대길이배열*/
/**
 * @method
 * @name fn_CheckMaxLength
 * @description desc
 * @param {string} vars desc
 * @param {string} names desc
 * @param {string} maxes desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CheckMaxLength = function(vars, names, maxes) {
    var len;
    for (var i = 0; i < vars.length; i++) {
        if (form[vars[i]] != null) {
            len = scwin.getByteLength(form[vars[i]].getValue());
            if (len > maxes[i]) {
                var msg = names[i] + '의 최대길이(' + maxes[i] + ')를 \n';
                msg += (len - maxes[i]);
                msg += ' Byte 만큼 초과하였습니다.\n수정후 저장하세요';
                alert(msg);
                form[vars[i]].focus();
                return false;
            }
        }
    }
    return true;
};
